-- Allow "swiss" as a bracket type.
--
-- brackets.type carries an inline CHECK listing the allowed types. Its name was
-- generated by Postgres, so rather than guess it, drop whichever CHECK on
-- brackets mentions the type column and recreate it under a known name.
--
-- Swiss games need no other schema change: later-round pairings live in the
-- existing bracket_nodes.source_a / source_b jsonb as { "type": "swiss", ... }
-- and are worked out by api/_lib/playoffResolve.js.

do $$
declare
  constraint_row record;
begin
  for constraint_row in
    select con.conname
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
    where nsp.nspname = 'public'
      and rel.relname = 'brackets'
      and con.contype = 'c'
      and pg_get_constraintdef(con.oid) ilike '%type%'
  loop
    execute format('alter table public.brackets drop constraint %I', constraint_row.conname);
  end loop;
end
$$;

alter table public.brackets
  add constraint brackets_type_check
  check (type = any (array['single_elim', 'double_elim', 'play_in', 'placement', 'swiss']));
